mapper.select:
/* selectMasterMdCpUserViewList */ SELECT USER_ID ,USER_ID AS KEP_USER_ID_MASK ,SUBSTR(USER_NAME,1,1)||'*'||SUBSTR(USER_NAME,3) AS USER_NAME ,COM_NAME ,DEPT_TEXT ,BUSINESS_COND ,BUSINESS_COND_TEXT ,TEL_NO ,EMAIL ,COM_CODE ,IRS_NO ,IRS_NAME ,USER_TYPE ,USER_TYPE_TEXT FROM ( SELECT L.USER_ID AS USER_ID, L.USER_NAME_LOC AS USER_NAME, C.COM_NAME_LOC AS COM_NAME, (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = L.COM_CODE AND TYPE = 'C001' AND CODE = DEPARTMENT) AS DEPT_TEXT, C.BUSINESS_COND, DECODE(C.BUSINESS_COND,'B','고객사','S','협력사','M','운영사') AS BUSINESS_COND_TEXT, L.PHONE_NUMBER AS TEL_NO, L.EMAIL, L.COM_CODE AS COM_CODE, C.IRS_NO, (SELECT IRS_NAME FROM KEPTIRSN K WHERE K.COM_CODE = C.COM_CODE AND K.IRS_NO = C.IRS_NO AND K.SITE = 'KA') IRS_NAME, L.USER_TYPE AS USER_TYPE, DECODE(L.USER_TYPE, 'A','Admin사용자', 'U','일반사용자') AS USER_TYPE_TEXT, L.REG_DATE FROM ICOMLUSR L, ICOMCMPY C WHERE L.COM_CODE = C.COM_CODE AND C.STATUS IN ('C','R') AND (L.STATUS IN ('C','R') OR (L.USER_TYPE = 'U' AND L.CHANGE_USER_TYPE = 'A' AND L.STATUS = 'A')) AND (C.COM_TYPE IS NULL OR C.COM_TYPE <> 'X') ) WHERE 1=1
AND USER_ID LIKE UPPER(#{st_search_user_id}) || '%'
AND USER_NAME LIKE '%' || #{st_search_user_name} || '%'
AND COM_NAME LIKE '%' || #{st_search_com_name} || '%'
AND USER_TYPE = #{st_search_user_type}
AND BUSINESS_COND = #{st_business_cond}
AND DEPT_TEXT LIKE '%' || #{st_dept_name} || '%'
ORDER BY REG_DATE DESC

mapper.update:

UPDATE ICOMLUSR
SET STATUS = 'D'
WHERE USER_ID = #{st_user_id}
